def translate(key: str, language: str = DEFAULT_LANGUAGE, **kwargs) -> str:
    lang = language if language in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE
    template = (
        TRANSLATIONS.get(lang, {}).get(key)
        or TRANSLATIONS[DEFAULT_LANGUAGE].get(key)
        or key
    )
    return template.format(**kwargs)


def language_label(language: str) -> str:
    return LANGUAGE_LABELS.get(language, LANGUAGE_LABELS[DEFAULT_LANGUAGE])


def option_labels(values: Iterable[str], key_map: dict[str, str], language: str) -> list[str]:
    return [translate(key_map.get(value, value), language) for value in values]
